fixtures.src/domain/ports/llm.ts:
/**
 * The language boundary of the agent.
 *
 * The agent has no tools: it can only speak JavaScript, and the REPL is the
 * only thing that executes it. This port is therefore deliberately tiny - it
 * hands over a conversation and receives JavaScript back.
 */

export type LlmRole = 'user' | 'assistant';

/**
 * How much room the model is given to think, on providers that grade it.
 *
 * The ladder is MiniMax-M3.1-Flash's. `max` is that model's own default, and
 * `none` is deliberately absent: the model rejects it outright.
 */
export type ReasoningEffort = 'low' | 'medium' | 'high' | 'xhigh' | 'max';

export const REASONING_EFFORTS: readonly ReasoningEffort[] = [
  'low',
  'medium',
  'high',
  'xhigh',
  'max',
];

/**
 * A block of the model's reasoning, as the provider reported it.
 *
 * The text is for the transcript; the signature is opaque and exists only to
 * travel back with the block. Providers that sign their reasoning reject a
 * block that came back altered or unsigned, so the two are kept together.
 */
export interface LlmThinkingBlock {
  readonly text: string;
  /** The provider's proof for this block, when it issued one. */
  readonly signature?: string;
}

export interface LlmMessage {
  readonly role: LlmRole;
  readonly text: string;
  /**
   * The reasoning that preceded this message's text, in the order it was
   * produced. It is replayed verbatim on the next request: interleaved
   * thinking depends on the model seeing its own thoughts, signatures and all.
   */
  readonly thinking?: readonly LlmThinkingBlock[];
}

export interface LlmRequest {
  readonly system: string;
  readonly messages: readonly LlmMessage[];
  readonly maxTokens: number;
}

export type LlmStopReason = 'end_turn' | 'max_tokens' | 'stop_sequence' | 'other';

/**
 * What one model call cost.
 *
 * The input is the prompt in total - plain input, cache reads and cache
 * writes put together - because that is the weight of the conversation,
 * not just the unbilled part of it.
 */
export interface LlmUsage {
  /** Prompt tokens in total, cache traffic included. */
  readonly input: number;
  /** Completion tokens of the reply. */
  readonly output: number;
  /** Prompt tokens served from the prompt cache. Present only when the API reports cache accounting at all. */
  readonly cached?: number;
}

export type LlmStreamEvent =
  | { readonly type: 'text'; readonly text: string }
  /** A chunk of the model's reasoning, when the model exposes it. */
  | { readonly type: 'thinking'; readonly text: string }
  | {
      readonly type: 'done';
      readonly stopReason: LlmStopReason;
      readonly usage?: LlmUsage;
      /** The whole reasoning of the reply, to be kept with the assistant turn. */
      readonly thinking?: readonly LlmThinkingBlock[];
    };

export interface LlmPort {
  stream(request: LlmRequest, signal: AbortSignal): AsyncIterable<LlmStreamEvent>;
}

fixtures.src/domain/ports/repl.ts:
/**
 * The only sensory organ of the agent.
 *
 * Every turn the agent writes one unit of JavaScript; the REPL runs it and
 * reports back what happened. There are four things that can happen inside a
 * unit, and each of them is an event:
 *
 *   - the unit names itself, before its body runs;
 *   - a tool runs, with the reason it was called;
 *   - the agent says something to the human;
 *   - the agent deposits something for the model to read next.
 *
 * There is nothing else. A unit has no return value to read, no console to
 * print to and no way to end the turn on its own: `say` is the only way out,
 * and `deposit` is the only way to talk back to the model.
 */

/** A step the agent named and described before it ran. */
export interface ReplStep {
  /** The handle the agent gave the step. */
  readonly name: string;
  /** What the step was for. */
  readonly description: string;
}

/** What happened while the unit ran. */
export type ReplEvent =
  /** The unit named itself. This arrives before the body runs. */
  | { readonly kind: 'step'; readonly name: string; readonly description: string }
  /** A tool ran: what it was, why it was called, and what came of it. */
  | {
      readonly kind: 'tool';
      readonly tool: string;
      readonly intent: string;
      readonly detail: string;
    }
  /** The agent said something to the human. The first one ends the round. */
  | { readonly kind: 'say'; readonly text: string }
  /** The agent deposited something for the model to read next. */
  | { readonly kind: 'deposit'; readonly text: string };

/** What came of one unit. */
export interface ReplOutcome {
  /** True when the unit ran to the end without throwing. */
  readonly ok: boolean;
  /** The error it threw, when it threw. */
  readonly error: string | undefined;
  /** The step that ran, when one did. */
  readonly step: ReplStep | undefined;
  /** True when the agent spoke to the human: the round is over. */
  readonly said: boolean;
}

export interface ReplPort {
  /**
   * Run one unit and report what happened.
   *
   * The events arrive while the unit runs, not after it: the human sees the
   * step's name while the step is still working.
   */
  exec(code: string, onEvent?: (event: ReplEvent) => void): Promise<ReplOutcome>;
}

fixtures.src/domain/ports/session.ts:
import type { QueueEntry } from '../queue.js';
import type { LlmMessage, LlmStopReason, LlmUsage, ReasoningEffort } from './llm.js';

/**
 * A conversation that outlives the process.
 *
 * The record has two kinds of truth in it. `message` and `queue` events are
 * normative: they are exactly what went into the conversation, and replaying
 * them rebuilds the context the model had. Everything else - steps, tools,
 * what was said, notes, turn boundaries - is for the human reading the
 * session afterwards.
 *
 * The file records what the model saw, not what the terminal drew.
 */

/** Why the turn ended. Used to tell a finished run from one that was cut off. */
export type SessionTurnStatus =
  | 'finished'
  | 'cancelled'
  | 'limit'
  | 'rejected'
  | 'error'
  /** The turn ran out of things to send: the queue was empty. */
  | 'idle';

/**
 * Where a message came from. A model's own words are not the human speaking.
 *
 * `human` and `observation` are v1: in v2 the human's words live in the
 * queue, and what the model concluded lives there too.
 */
export type SessionMessageOrigin = 'human' | 'assistant' | 'observation' | 'resume';

/** What a new session is told about itself. The store fills in id, time and cwd. */
export interface SessionStart {
  readonly model: string;
  readonly effort: ReasoningEffort;
  readonly maxTokens: number;
  readonly maxSteps: number;
  /** The system prompt's hash, so a later resume can see that it moved. */
  readonly systemPromptHash: string;
  readonly agent: string;
}

/** The first line of every session file. */
export interface SessionHeader extends SessionStart {
  /**
   * The schema version of the file, not of the app.
   *
   * A v1 file has a world and its own event types; a v2 file has the queue.
   */
  readonly v: 1 | 2;
  readonly type: 'session';
  readonly id: string;
  readonly at: string;
  readonly cwd: string;
  /** A v1 file's world path. Read for compatibility; a v2 file has none. */
  readonly world?: string;
}

export type SessionEventInput =
  | { readonly type: 'turn.start' }
  | {
      readonly type: 'message';
      readonly message: LlmMessage;
      readonly origin: SessionMessageOrigin;
      readonly usage?: LlmUsage;
      readonly stopReason?: LlmStopReason;
    }
  /**
   * What went into the request.
   *
   * The entries are kept, not the text that was rendered from them, so a
   * resume rebuilds the request exactly - labels and all.
   */
  | { readonly type: 'queue'; readonly entries: readonly QueueEntry[] }
  | { readonly type: 'step'; readonly name: string; readonly description: string }
  | {
      readonly type: 'tool';
      readonly tool: string;
      readonly intent: string;
      readonly detail: string;
    }
  | { readonly type: 'say'; readonly text: string }
  | { readonly type: 'note'; readonly text: string }
  | { readonly type: 'turn.end'; readonly status: SessionTurnStatus }
  | { readonly type: 'title'; readonly text: string };

/** An event as it sits in the file: the payload plus its place in the log. */
export type SessionEvent = SessionEventInput & {
  readonly seq: number;
  readonly at: string;
};

/** What a listing needs, without reading the conversation. */
export interface SessionSummary {
  readonly id: string;
  readonly startedAt: string;
  readonly updatedAt: string;
  readonly model: string;
  readonly turns: number;
  /** The first thing the human said, shortened for a list. */
  readonly firstUserText?: string;
  /** A human's name for the session, when one was given. */
  readonly title?: string;
}

export interface SessionWriter {
  readonly id: string;
  append(event: SessionEventInput): void;
  /** Make what has been written durable. Called at the end of a turn. */
  checkpoint(): void;
  close(): void;
}

export interface LoadedSession {
  readonly header: SessionHeader;
  readonly events: readonly SessionEvent[];
  readonly summary: SessionSummary;
  /** Lines that could not be read - a torn tail, or a stranger's edit. */
  readonly ignoredLines: number;
  readonly writer: SessionWriter;
}

export interface SessionStore {
  /** Start a session, returning the writer that appends to it. */
  create(start: SessionStart): SessionWriter;
  /** Open an existing session by id or unique id prefix. */
  open(idOrPrefix: string): LoadedSession;
  /** Summaries for this project, most recently used first. */
  list(): readonly SessionSummary[];
}

